import { AppShell, Button, ConsentCheckbox, Field } from "@wizard/ui-kit";
import { useEntityMutation, useState } from "@wizard/sdk";

export default function Main() {
  const [form, setForm] = useState({ name: "", phone: "", consent: false });
  const requests = useEntityMutation("request");
  return (
    <AppShell title={"Алтайские травяные чаи и мёд: интернет-магазин с фасовками, промокодами и доставкой"}>
      <p>{"Мы семейное дело из Барнаула: собираем и сушим травяные сборы, качаем мёд на своей пасеке, продаём по всей России. Нужен интернет-магазин. Каталог с разделами «чаи», «мёд», «подарочные наборы»; у товара фото, состав, история сбора и фасовки — 50, 100 или 250 граммов у чая и 250 граммов, 0,5 или 1 килограмм у мёда, у каждой фасовки своя цена и свой остаток. Покупатель кладёт товары в корзину, вводит промокод, если есть, и платит картой через ЮKassa с чеком на почту. Доставка — Почтой России или СДЭК до пункта выдачи, стоимость считаем по весу заказа; от трёх тысяч рублей доставка бесплатная. Мёд зимой не отправляем в регионы с морозами ниже тридцати — пусть сайт предупреждает. Владелец в кабинете видит заказы и оплаты, меняет статусы, вписывает трек-номер, ведёт остатки и промокоды. Хотим тёплый сайт с фотографиями гор и пасеки. С покупателями из Европы переписывается клиент, его почта клиент."}</p>
      <ul>
        <li>{"Корзина"}</li>
        <li>{"Фасовки с ценой и остатком"}</li>
        <li>{"Промокоды"}</li>
        <li>{"Оплата ЮKassa"}</li>
        <li>{"Доставка Почтой России и СДЭК"}</li>
      </ul>
      <p>{"Бесплатная доставка от 3 000 ₽"}</p>
      <p>{"Трек-номер в заказе"}</p>
      <form onSubmit={(e) => { e.preventDefault(); void requests.create({ contact_name: form.name, contact_phone: form.phone }, { consent: true }); }}>
        <Field name="contact_name" label="Имя" type="string" value={form.name} onChange={(v) => setForm({ ...form, name: String(v) })} />
        <Field name="contact_phone" label="Телефон" type="phone" value={form.phone} onChange={(v) => setForm({ ...form, phone: String(v) })} />
        <ConsentCheckbox checked={form.consent} onChange={(v) => setForm({ ...form, consent: v })} />
        <Button type="submit">{"Отправить заявку"}</Button>
      </form>
    </AppShell>
  );
}
